Lemma Forall_off_sub : forall (Xl : list (Z * Z)) O n A k,
  Forall (fun iv : Z * Z => O + n <= fst iv \/ snd iv <= O) Xl -> O <= A -> A + k <= O + n -> Forall (fun iv : Z * Z => A + k <= fst iv \/ snd iv <= A) Xl.
Proof. intros Xl O n A k M H1 H2. eapply Forall_impl; [| exact M]. intros [l h] K. cbn [fst snd] in *. lia. Qed.

Lemma ao_up : forall LBn O n, aobj LB0 LF O n -> aobj (LBn ++ LB0) ((1, ff, fp) :: LF) O n.
Proof.
  intros LBn O n AO. eapply aobj_LF_mono; [eapply aobj_LB_mono; [exact AO| intros b Hb; apply in_or_app; right; exact Hb]| intros f Hf; right; exact Hf].
Qed.

Definition kxc (sx : as_St H) (LBn : list block) (mh m1 m2 : mem) (SP : Z) (Xc XS' : list (Z * Z)) : Prop :=
  as_RHEAP H sx (LBn ++ LB0) mh /\ as_RFS H ((1, ff, fp) :: LF) m1 /\ Forall (fs_scratch H ((1, ff, fp) :: LF)) XS'
  /\ xpres H (LBn ++ LB0) SP (Xc ++ XS') m1 m2 /\ aceil <= SP /\ Forall noshadow Xc.

Section CALLEE.
