  (* [comment removed for export] *)
  Lemma kx_mbuf : forall O n b es insz, aobj LB0 LF O n -> O <= b -> b + 64 <= O + n -> AMBufOwn (LBn ++ LB0) es -> AMBuf m1 b es insz ->
