  (* [comment removed for export] *)
  Lemma kx_xp : forall XS,
    xpres H LB0 (bv_unsigned sp) (put_X P E (ps_L d0) (ps_es d0) ++ XS) m0 m1 -> SP <= bv_unsigned sp ->
    (forall a, aclient_addr H LB0 (bv_unsigned sp) a -> rin_ivs Xc a -> rin_ivs (put_X P E (ps_L d0) (ps_es d0) ++ XS) a) ->
    xpres H LB0 (bv_unsigned sp) (put_X P E (ps_L d0) (ps_es d0) ++ XS ++ XS') m0 m2.
  Proof.
    open_KX. intros XS XP0 HS COV. eapply xpres_trans.
    - eapply xpres_weaken; [exact XP0| lia| intros b Hb; exact Hb|].
      intros a K. rewrite app_assoc. apply rin_ivs_app. left. exact K.
    - intros a Ha [Hc NX]. apply XPx; [exact Ha|]. split.
      + eapply (aclient_addr_weaken H); [exact Hc| exact HS| intros b Hb; apply in_or_app; right; exact Hb].
      + intros K. apply NX. rewrite app_assoc. apply rin_ivs_app. apply rin_ivs_app in K. destruct K as [K|K]; [left; exact (COV a Hc K)| right; exact K].
  Qed.
End CALLEE.

(* [comment removed for export] *)
Lemma hdr_LB_mono : forall LB LB' m h, HdrOwnA LB m h -> (forall b, In b LB -> In b LB') -> HdrOwnA LB' m h.
Proof.
  intros LB LB' m h (O1 & O2 & R1 & R2) HL.
  assert (K : forall ptr len, ASvOwn LB m ptr len -> ASvOwn LB' m ptr len).
  { intros ptr len [Z0|(L1 & p & cs & IN & C & AD)]; [left; exact Z0| right]. split; [exact L1|]. exists p, cs. split; [apply HL; exact IN| split; [exact C| exact AD]]. }
  split; [exact (K _ _ O1)|]. split; [exact (K _ _ O2)|]. split; [exact R1| exact R2].
Qed.

(* [comment removed for export] *)
(* [comment removed for export] *)
Definition bp_frame4 (m : mem) : Prop :=
  exists j0 j128 j152,
       rw_cells bsegs m spa (bp_locals175 H X j0 j128 j152)
    /\ rw_cells bsegs m (spa + 184) gap
    /\ rw_cells bsegs m (bv_unsigned sp + -104) (bp_saves s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra)
    /\ rw_cells bsegs m fp [C1 (b8 1)].
Definition bp_frameF (m : mem) : Prop :=
  exists ja j48 jb j80 jc j112, rw_cells bsegs m ff (bp_ffr spa fp ja j48 jb j80 jc j112) /\ rw_cells bsegs m (sh ff) (bp_sh F8b F8b F8b).

Lemma frame_split : forall m p, bp_frame H X m p <-> bp_frame4 m /\ bp_frameF m /\ rw_cells bsegs m (spa + 176) [C8 (wz p)].
Proof.
  intros m p. split.
  - intros (j0 & j128 & j152 & ja & j48 & jb & j80 & jc & j112 & LOC & GAP & SAV & FFR & SH & FL).
    apply (proj1 (bp_locals_split H MX CX X XOK m j0 j128 j152 p)) in LOC. destruct LOC as [LOC IN].
    split; [exists j0, j128, j152; repeat (split; [assumption|]); exact FL|]. split; [exists ja, j48, jb, j80, jc, j112; split; assumption| exact IN].
  - intros ((j0 & j128 & j152 & LOC & GAP & SAV & FL) & (ja & j48 & jb & j80 & jc & j112 & FFR & SH) & IN).
    exists j0, j128, j152, ja, j48, jb, j80, jc, j112. split; [apply (proj2 (bp_locals_split H MX CX X XOK m j0 j128 j152 p)); split; assumption|].
    repeat (split; [assumption|]); exact FL.
Qed.

(* [comment removed for export] *)
Definition wg5 (iv : Z * Z) : Prop :=
  (aceil <= fst iv /\ snd iv <= spa) \/ (fst iv = spa + 176 /\ snd iv = spa + 184)
  \/ (P <= fst iv <= snd iv /\ snd iv <= P + 80)
  \/ (fst iv = E /\ snd iv = E + 24) \/ (fst iv = AG_HTTP_CAT /\ snd iv = AG_HTTP_CAT + 64).
(* [comment removed for export] *)
Definition wg4 (iv : Z * Z) : Prop :=
  wg5 iv \/ (fst iv = P + 240 /\ snd iv = P + 241) \/ (ff + 32 <= fst iv <= snd iv /\ snd iv <= ff + 128) \/ (sh ff <= fst iv <= snd iv /\ snd iv <= sh ff + 16).

Lemma wg5_wg4 : forall W, Forall wg5 W -> Forall wg4 W.
Proof. intros W FW. eapply Forall_impl; [| exact FW]. intros iv K. left. exact K. Qed.

