Definition inv_k (m : mem) (rdi : byte) (XS : list (Z * Z)) : Prop :=
  (exists errv, rw_cells bsegs m (errno_addr tp) [C4 errv]) /\ as_rauxv_ok H m B
  /\ bp_frame4 m /\ bp_frameF m /\ bp_side H X m
  /\ rw_cells bsegs m (P + 240) [C1 rdi] /\ (AFieldTabZero m \/ FT m)
  /\ Forall (fs_scratch H LF) XS /\ Forall (fun iv => In iv XS) (bp_fsw H X)
  /\ xpres H LB0 (bv_unsigned sp) (put_X P E (ps_L d0) (ps_es d0) ++ XS) m0 m.

Lemma keep_k : forall W m m' s LB rdi XS, Forall wg5 W -> munch W m m' -> wmono bsegs m m' -> as_RHEAP H s (LB ++ LB0) m ->
  inv_k m rdi XS -> inv_k m' rdi XS.
Proof.
  open_X. intros W m m' s LB rdi XS FW MU WM RH ([errv ERR] & AUX & FR4 & FRF & SD & RDI & FTS & FSX & INX & XP).
  pose proof (env_facts H HH MX CX X XOK) as (Pl & Ph & APP & FOP & El & Eh & APE & FOE & Wl & Wh & APW & FOW & CEIL & LO & SPAR & SPH). rewrite BPUT_STACK_val in LO.
  pose proof aceil_facts as (AF1 & _).
  pose proof (stat_open H MX CX X XOK) as (_ & _ & _ & _ & _ & DPE & _).
  pose proof (wg5_wg4 W FW) as FW4. pose proof (wg4_wg7 W FW4) as FW7. pose proof (wg4_wg W FW4) as FWg.
  pose proof (keep_frameF W m m' FW MU WM FRF) as FRF'.
  split; [exists errv; exact (keep_errno H HH MX CX X XOK _ _ _ _ FWg MU WM ERR)|].
  split; [exact (keep_rauxv H HH MX CX X XOK _ _ _ _ _ _ FWg MU WM RH AUX)|].
  split; [exact (keep_frame4 W m m' FW4 MU WM FR4)|]. split; [exact FRF'|].
  split; [exact (keep_side H HH MX CX X XOK _ _ _ _ FW7 MU WM (frameF_row _ FRF') eq_refl SD)|].
  split. { eapply rw_cells_transport; [exact RDI| exact MU| exact WM|]. cbn [cells_size csize Nat.add]. apply disjoint_from_Forall. eapply Forall_impl; [| exact FW].
           intros [l h] K. unfold wg5 in K. cbn [fst snd] in *. unfold PARSER_SIZE, AG_HTTP_CAT, AIMG_TOP in *.
           destruct K as [K|[K|[K|[K|K]]]]; first [clear - K CEIL LO SPAR Ph Pl DPE AF1; lia]. }
  split; [exact (keep_ft H HH MX CX X XOK _ _ _ FWg MU WM FTS)|]. split; [exact FSX|]. split; [exact INX|].
  exact (keep_xpres H HH MX CX X XOK _ _ _ _ FWg MU WM INX XP).
Qed.

Lemma kx_k : forall s LBn m1 m2 SP Xc XS' sq LBx rdi XS errv,
