  (forall A k, ff <= A -> A + k <= ff + 128 -> Forall (fun iv : Z * Z => A + k <= fst iv \/ snd iv <= A) Xc) ->
  Forall (fun iv : Z * Z => sh ff + 16 <= fst iv \/ snd iv <= sh ff) Xc ->
  Forall (fun iv : Z * Z => fp + 1 <= fst iv \/ snd iv <= fp) Xc ->
  (forall a, aclient_addr H LB0 (bv_unsigned sp) a -> rin_ivs Xc a -> rin_ivs (put_X P E (ps_L d0) (ps_es d0) ++ XS) a) ->
